class PhaseRing {
  constructor(radius, resolution, speed) {
    if (typeof radius !== 'number' || !Number.isFinite(radius) || radius <= 0) {
      throw new TypeError('radius must be a positive finite number');
    }
    if (!Number.isInteger(resolution) || resolution < 3) {
      throw new TypeError('resolution must be an integer of at least 3');
    }
    if (typeof speed !== 'number' || !Number.isFinite(speed) || speed < 0) {
      throw new TypeError('speed must be a non-negative finite number');
    }
    this.radius = radius;
    this.resolution = resolution;
    this.speed = speed;
    this.phase = 0;
  }

  step(delta) {
    if (typeof delta !== 'number' || !Number.isFinite(delta) || delta < 0) {
      throw new TypeError('delta must be a non-negative finite number');
    }
    const turn = Math.PI * 2;
    this.phase = (this.phase + delta) % turn;
    return this.phase;
  }

  snapshot() {
    const points = [];
    const turn = Math.PI * 2;
    for (let index = 0; index < this.resolution; index += 1) {
      const angle = turn * index / this.resolution;
      points.push({
        x: this.radius * Math.cos(angle),
        y: 0,
        z: this.radius * Math.sin(angle),
        intensity: (Math.sin(angle + this.phase) + 1) / 2
      });
    }
    return points;
  }
}

module.exports = { PhaseRing };

