'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['PhaseRing']);
const { PhaseRing } = api;

for (const args of [
  [0, 3, 1], [-1, 3, 1], [NaN, 3, 1], [Infinity, 3, 1], ['1', 3, 1],
  [1, 2, 1], [1, 3.5, 1], [1, NaN, 1], [1, '3', 1],
  [1, 3, -1], [1, 3, NaN], [1, 3, Infinity], [1, 3, '1']
]) {
  assert.throws(() => new PhaseRing(...args), TypeError);
}

const ring = new PhaseRing(2, 4, 0.5);
const initial = ring.snapshot();
assert.strictEqual(initial.length, 4);
function close(actual, expected, epsilon = 1e-12) {
  assert.ok(Math.abs(actual - expected) <= epsilon, `${actual} != ${expected}`);
}
const expectedCoordinates = [
  [2, 0], [0, 2], [-2, 0], [0, -2]
];
for (let i = 0; i < 4; i += 1) {
  assert.deepStrictEqual(Object.keys(initial[i]), ['x', 'y', 'z', 'intensity']);
  close(initial[i].x, expectedCoordinates[i][0]);
  assert.strictEqual(initial[i].y, 0);
  close(initial[i].z, expectedCoordinates[i][1]);
  close(initial[i].intensity, (Math.sin(i * Math.PI / 2) + 1) / 2);
}
const initialAgain = ring.snapshot();
assert.notStrictEqual(initialAgain, initial);
assert.notStrictEqual(initialAgain[0], initial[0]);
assert.deepStrictEqual(initialAgain, initial);
initial[0].x = 999;
initial.pop();
close(ring.snapshot()[0].x, 2);
assert.strictEqual(ring.snapshot().length, 4);

close(ring.step(2), 1);
const after = ring.snapshot();
close(after[0].intensity, (Math.sin(1) + 1) / 2);
close(ring.step(4 * Math.PI), 1);
assert.deepStrictEqual(ring.snapshot(), after);
for (const bad of [-1, NaN, Infinity, '1', null, undefined]) {
  assert.throws(() => ring.step(bad), TypeError);
}
const stationary = new PhaseRing(1, 3, 0);
assert.strictEqual(stationary.step(100), 0);
assert.strictEqual(stationary.snapshot().length, 3);

